<?php
$esc = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES, "UTF-8");
$categories = $data["categories"] ?? [];
$selected = $data["selected"] ?? null;
$breakdown = $data["breakdown"] ?? ["assigned" => [], "stock" => []];
$assets = $data["assets"] ?? ["items" => [], "total" => 0, "page" => 1, "totalPages" => 1, "perPage" => 25, "offset" => 0];
$filters = $data["filters"] ?? [];
$status = $filters["status"] ?? "ALL";
$url = static function (array $changes = []) use ($selected, $filters): string {
    $query = array_merge(["category" => $selected["categoryCode"] ?? "", "status" => $filters["status"] ?? "ALL", "assigneeType" => $filters["assigneeType"] ?? "", "groupType" => $filters["groupType"] ?? "", "groupId" => $filters["groupId"] ?? "", "search" => $filters["search"] ?? "", "perPage" => $filters["perPage"] ?? 25], $changes);
    return BASEURL . "/AssetDirectory?" . http_build_query(array_filter($query, static fn($v) => $v !== ""));
};
$exportQuery = $selected ? http_build_query([
    "category" => $selected["categoryCode"],
    "status" => $status,
    "assigneeType" => $filters["assigneeType"] ?? "",
    "groupType" => $filters["groupType"] ?? "",
    "groupId" => $filters["groupId"] ?? "",
    "search" => $filters["search"] ?? "",
]) : "";
$total = array_sum(array_column($categories, "totalAssets"));
$assigned = array_sum(array_column($categories, "assignedAssets"));
$stock = array_sum(array_column($categories, "inStockAssets"));
?>
