s="text-right"><button class="btn btn-minier btn-info asset-detail-link history-btn" type="button" data-asset-details="<?= $esc($asset["assetNum"]) ?>"><i class="fa fa-history"></i> History</button></td></tr><?php endforeach; ?></tbody></table></div>
