<script>
(function(){
  function text(value){return value==null||value===''?'-':String(value)}
  function escapeHtml(value){var div=document.createElement('div');div.textContent=text(value);return div.innerHTML}
  function dateOnly(value){var raw=text(value);return raw==='-'?raw:raw.substring(0,10)}
  function returnToRosterAfter($child){$child.one('hidden.bs.modal',function(){$('#assignmentRosterModal').modal('show');});}
  function handoffFromRoster(openChild){var $roster=$('#assignmentRosterModal');$roster.one('hidden.bs.modal',openChild);$roster.modal('hide');}
  document.addEventListener('click',function(event){
    var countLink=event.target.closest('.number-assigned,.number-department');
    if(!countLink)return;
    event.preventDefault();
    var targetUrl=new URL(countLink.href,window.location.href), category=targetUrl.searchParams.get('category'), type=countLink.classList.contains('number-department')?'DEPARTMENT':'USER', $=window.jQuery;
    $('#assignmentRosterTitle').html('<i class="fa fa-users"></i> '+escapeHtml(type==='USER'?'User assignments':'Department assignments'));
    $('#assignmentRosterIdHeader').text(type==='USER'?'Employee ID':'Type');
    $('#assignmentRosterLoading').removeClass('hide');$('#assignmentRosterError,#assignmentRosterContent').addClass('hide');
    $('#assignmentRosterModal').modal('show');
    $.getJSON('<?= BASEURL ?>/AssetDirectory/assignments/'+encodeURIComponent(category)+'?type='+encodeURIComponent(type)).done(function(data){
      var html='';(data.rows||[]).forEach(function(row){var idCell=type==='USER'&&row.empId?'<button type="button" class="btn btn-link btn-xs employee-summary-link" data-employee="'+escapeHtml(row.empId)+'">'+escapeHtml(row.empId)+'</button>':'Department';html+='<tr><td>'+escapeHtml(row.sl)+'</td><td>'+idCell+'</td><td>'+escapeHtml(row.assignedTo)+'</td><td>'+escapeHtml(row.department)+'</td><td><button type="button" class="btn btn-link btn-xs asset-detail-link" data-asset-details="'+escapeHtml(row.assetNum)+'">'+escapeHtml(row.assetNum)+'</button></td><td>'+escapeHtml(dateOnly(row.issueDate))+'</td></tr>';});
      if(!html)html='<tr><td colspan="6" class="text-center text-muted">No assignments found.</td></tr>';
      $('#assignmentRosterRows').html(html);$('#assignmentRosterSummary').text(text(data.category)+' · '+text(data.total)+' assignment'+(Number(data.total)===1?'':'s')+(data.truncated?' · first 5,000 shown':''));$('#assignmentRosterLoading').addClass('hide');$('#assignmentRosterContent').removeClass('hide');
    }).fail(function(xhr){$('#assignmentRosterLoading').addClass('hide');$('#assignmentRosterError').removeClass('hide').text((xhr.responseJSON&&xhr.responseJSON.error)||'Unable to load assignments.');});
  });
  function openEmployee(id,returnToRoster){
    var $=window.jQuery,$modal=$('#employeeSummaryModal');
    if(returnToRoster)returnToRosterAfter($modal);
    $('#employeeSummaryTitle').html('<i class="fa fa-user"></i> Employee '+escapeHtml(id));
    $('#employeeSummaryLoading').removeClass('hide');
    $('#employeeSummaryError,#employeeSummaryContent').addClass('hide');
    $modal.modal('show');
    $.getJSON('<?= BASEURL ?>/AssetDirectory/employee/'+encodeURIComponent(id)).done(function(data){
      var employee=data.employee||{}, rows=data.transactions||[], html='';
      $('#employeeSummaryId').text(text(employee.empId));
      $('#employeeSummaryName').text(text(employee.fullname));
      $('#employeeSummaryDepartment').text(text(employee.department||employee.deptName));
      rows.forEach(function(row){html+='<tr><td>'+escapeHtml(row.assetNum)+'</td><td>'+escapeHtml(row.category_name||row.category||row.categoryName)+'</td><td>'+escapeHtml(dateOnly(row.issue_date||row.issueDate))+'</td><td>'+escapeHtml(row.status||row.issue_status)+'</td></tr>';});
      if(!html)html='<tr><td colspan="4" class="text-center text-muted">No asset transactions found.</td></tr>';
      $('#employeeSummaryTransactions').html(html);
      $('#employeeSummaryLoading').addClass('hide');$('#employeeSummaryContent').removeClass('hide');
    }).fail(function(xhr){$('#employeeSummaryLoading').addClass('hide');$('#employeeSummaryError').removeClass('hide').text((xhr.responseJSON&&xhr.responseJSON.error)||'Unable to load employee details.');});
  }
  document.addEventListener('click',function(event){
    var link=event.target.closest('.employee-summary-link');
    if(!link)return;
    event.preventDefault();
    var id=link.getAttribute('data-employee');
    if(!id)return;
    if(link.closest('#assignmentRosterModal')){event.stopImmediatePropagation();handoffFromRoster(function(){openEmployee(id,true);});return;}
    openEmployee(id,false);
  });
  document.addEventListener('click',function(event){
    var link=event.target.closest('#assignmentRosterModal .asset-detail-link');
    if(!link)return;
    event.preventDefault();event.stopImmediatePropagation();
    var asset=link.getAttribute('data-asset-details');
    handoffFromRoster(function(){var $child=$('#sharedAssetDetailModal');returnToRosterAfter($child);var trigger=document.createElement('button');trigger.type='button';trigger.className='asset-detail-link';trigger.setAttribute('data-asset-details',asset);trigger.style.display='none';document.body.appendChild(trigger);trigger.click();trigger.remove();});
  },true);
})();
</script>
